/* Synthetic current-scope facts only: no network, credentials or source orders. */
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const base=path.join(__dirname,'../admin-preview'),renderer=fs.readFileSync(path.join(base,'live-success-analysis.js'),'utf8');
function api(){const c={};c.window=c;vm.createContext(c);for(const name of ['live-provider-aliases.js','live-report-data.js','live-provider-summary.js'])vm.runInContext(fs.readFileSync(path.join(base,name),'utf8'),c);vm.runInContext(renderer,c);return c.HensemLiveSuccessAnalysis;}
const A={id:'native-ar',name:'Same platform',source:'AR',country:'印度'},B={...A,id:'native-newar',source:'NEW_AR'},W={...A,id:'native-wg',source:'WG'};
const row=(direction='charge',all=10,success=4,provider='ATPay')=>({direction,all_count:all,success_count:success,provider,currency:'INR'});
const payment=(platform,rows,summary)=>({platform,groups:{provider:rows},...(summary===undefined?{}:{summary})});
const ticket=(platform,direction='charge',total=10,success=4,provider='ATPay',complete=true)=>({platformId:platform.id,country:platform.country,source:platform.source,provider,direction,uniqueOrderCount:total,uniqueSuccessCount:success,uniqueCoverage:{status:complete?'complete':'partial',complete}});
function props(overrides={}){const L={pageQueried:true,dirty:false,from:'2026-10-03T00:00:00',to:'2026-10-03T23:59:59',queryPlatforms:[A,B],results:[payment(A,[row()]),payment(B,[row('charge',5,1,'ATPay-QR')])],queryFailures:[],feeLookupRows:[],feeLookupLoading:false,feeLookupError:'',country:'印度',workorders:{startDate:'2026-10-03',endDate:'2026-10-03',byPlatformProvider:[ticket(A),ticket(A,'withdraw',5,5),ticket(B,'charge',6,1,'ATPay-QR',false)]},...overrides};return {L,scopeMatches:true,workordersScopeMatches:true};}
test('DUOLI current-status success never becomes a payment-time rate in either direction',()=>{
 const p={...A,id:'duoli-id',name:'UANG',source:'duoli',country:'印尼',capabilities:{chargeSuccessTimeAvailable:false,withdrawSuccessTimeAvailable:false}},rows=[row('charge',20,0,'ObservedPay'),row('withdraw',10,0,'ObservedPay')],a=api(),input=props({queryPlatforms:[p],results:[payment(p,rows,rows)],workorders:null});
 const model=a.buildModel(input);assert.equal(model.rows[0].charge[0].value,null);assert.equal(model.rows[0].withdraw[0].value,null);
 const html=a.render(input);assert.match(html,/多利/);assert.match(html,/代收成功时间/);assert.match(html,/代付成功时间/);assert.doesNotMatch(html,/>0\.00%/);
});
test('canonical provider rows keep native platform identity and three vertical rate-only matrices',()=>{
 const a=api(),p=props({successDateNotice:'成功率分析按一个当地日展示，已选择 2026-10-03 全天。'}),before=JSON.stringify(p),model=a.buildModel(p);assert.equal(model.rows.length,1);assert.equal(model.rows[0].provider,'ATPay');assert.deepEqual(Array.from(model.rows[0].charge,v=>v.value),[40,20]);assert.equal(model.rows[0].workorder[0].value,60);assert.equal(model.rows[0].workorder[0].partial,false);assert(Math.abs(model.rows[0].workorder[1].value-100/6)<1e-10);assert.equal(model.rows[0].workorder[1].partial,true);
 const html=a.render(p);assert.equal((html.match(/<table /g)||[]).length,3);assert.equal((html.match(/<th scope="row">ATPay<\/th>/g)||[]).length,2);assert.match(html,/新AR/);assert.match(html,/状态 4/);assert.match(html,/不代表实际到账/);assert.match(html,/完整原单号去重/);assert.doesNotMatch(html,/全部金额|手续费|到账成功金额/);assert.doesNotMatch(html,/按一个当地日展示|已选择 2026-10-03 全天|success-analysis-context|success-analysis-method|统计口径|平台当地日期 · 提交笔数从多到少/);assert.equal(JSON.stringify(p),before);
});
test('strict below-40 color applies to all matrices, unknown neutral and above-100 rates are preserved',()=>{
 const a=api(),p=props({queryPlatforms:[A],results:[payment(A,[row('charge',100,39),row('withdraw',10,4)])],workorders:{byPlatformProvider:[ticket(A,'charge',100,39),ticket(A,'withdraw',0,0)]}});let html=a.render(p);assert.equal((html.match(/<tbody>.*?<\/tbody>/g).join('').match(/class="success-rate-low"/g)||[]).length,4);assert.equal((html.match(/<tfoot.*?<\/tfoot>/g).join('').match(/class="success-rate-low"/g)||[]).length,2);assert.match(html,/>40\.00%<\/span>/);assert.match(html,/>39\.00%/);
 p.L.results=[payment(A,[row('charge',10,12),row('withdraw',10,null)])];p.L.workorders.byPlatformProvider=[ticket(A,'charge',0,0)];html=a.render(p);assert.match(html,/>120\.00%<\/span>/);assert.doesNotMatch(html,/success-rate-low/);assert.match(html,/>—<\/span>/);
});
test('workorder combined rate uses dedup original counts and preserves absent, unknown and duplicate cohort evidence',()=>{
 const a=api(),p=props({queryPlatforms:[A],results:[payment(A,[row()])],workorders:{byPlatformProvider:[ticket(A,'charge',8,4),ticket(A,'withdraw',2,2)]}}),work=()=>a.buildModel(p).rows[0].workorder[0];assert.equal(work().value,60);assert.equal(work().partial,false);
 p.L.workorders.byPlatformProvider.pop();assert.equal(work().value,50);assert.equal(work().partial,true);p.L.workorders.byPlatformProvider.push(ticket(A,'withdraw',null,0));assert.equal(work().value,null);p.L.workorders.byPlatformProvider=[ticket(A),ticket(A,'charge',10,3,'ATPay-QR')];assert.equal(work().value,null);
 p.L.workorders.byPlatformProvider=[{...ticket(A),uniqueOrderCount:null,submittedCount:999,successCount:999}];assert.equal(work().value,null);p.L.workorders.byPlatformProvider=[ticket(A,'charge',1,2)];assert.equal(work().value,null);
});
