 const a=api(),p=props({queryPlatforms:[A,W],results:[payment(A,[row('withdraw',10,5,'Small'),row('withdraw',0,0,'Zero')]),payment(W,[row('withdraw',50,20,'Busy WG')])],workorders:null}),m=a.buildModel(p);
