 assert.equal(m.rows[0].charge[0].value,100);assert.equal(m.rows[0].charge[1].value,50);assert(Math.abs(m.rows[0].charge[2].value-100/3)<1e-10);assert.equal(m.rows[0].charge[3].value,null);
